# -*- coding: utf-8 -*-

import sys
import os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from baserequest import BaseRequest
# ============ MT4 ORDER TYPES (Replaces OANDA) ============

class OrderType:
    """MT4 Order Types"""
    STOP = "STOP"
    LIMIT = "LIMIT"
    MARKET = "MARKET"
    STOP_LIMIT = "STOP_LIMIT"


class OrderPositionFill:
    """Position Fill Types"""
    DEFAULT = "DEFAULT"
    OPEN_ONLY = "OPEN_ONLY"
    REDUCE_FIRST = "REDUCE_FIRST"
    REDUCE_ONLY = "REDUCE_ONLY"


class TimeInForce:
    """Time in Force"""
    GTC = "GTC"  # Good Till Cancelled
    DAY = "DAY"
    IOC = "IOC"
    FOK = "FOK"


class Units:
    """Units wrapper"""
    def __init__(self, units):
        self.value = str(units)


class PriceValue:
    """Price value wrapper"""
    def __init__(self, price):
        self.value = str(price)


class StopOrderRequest(BaseRequest):
    """create a StopOrderRequest.

    StopOrderRequest is used to build the body for an StopOrder.
    The body can be used to pass to the OrderCreate endpoint.
    
    NOTE: This has been adapted from OANDA to support MT4 order structure.
    For MT4, actual order execution is handled via the file bridge.
    This class now serves as a data structure for order parameters.
    """

    def __init__(self,
                 instrument,
                 units,
                 price,
                 priceBound=None,
                 positionFill=OrderPositionFill.DEFAULT,
                 timeInForce=TimeInForce.GTC,
                 gtdTime=None,
                 clientExtensions=None,
                 takeProfitOnFill=None,
                 stopLossOnFill=None,
                 trailingStopLossOnFill=None,
                 tradeClientExtensions=None):
        """
        Instantiate a StopOrderRequest.

        Parameters
        ----------

        instrument : string (required)
            the instrument to create the order for (e.g., 'EURUSD' for MT4)

        units : integer (required)
            the number of units. If positive the order results in a LONG
            order. If negative the order results in a SHORT order

        price : float (required)
            the treshold price indicating the price to activate the order

        Example
        -------

        >>> from mt4_stop_order import StopOrderRequest
        >>> from mt4_price_provider import get_mt4_prices
        >>>
        >>> # Create a stop order request (data structure)
        >>> order = StopOrderRequest(
        ...     instrument="EURUSD",
        ...     units=10000,
        ...     price=1.0950,
        ...     stopLossOnFill=1.0900,
        ...     takeProfitOnFill=1.1000
        ... )
        >>> 
        >>> # For actual MT4 execution, use the MT4 client:
        >>> mt4 = get_mt4_prices()
        >>> 
        >>> # For stop order, you would typically use a market order with limits
        >>> if units > 0:
        >>>     result = mt4.buy(instrument, volume, stopLossOnFill, takeProfitOnFill)
        >>> else:
        >>>     result = mt4.sell(instrument, volume, stopLossOnFill, takeProfitOnFill)
        """
        super(StopOrderRequest, self).__init__()

        # by default for a STOP order
        self._data.update({"type": OrderType.STOP})

        # required
        self._data.update({"instrument": instrument})
        self._data.update({"units": Units(units).value})
        self._data.update({"price": PriceValue(price).value})

        # optional, but required if timeInForce.GTD
        self._data.update({"gtdTime": gtdTime})
        if timeInForce == TimeInForce.GTD and not gtdTime:
            raise ValueError("gtdTime missing")

        # optional
        self._data.update({"timeInForce": timeInForce})
        self._data.update({"priceBound": priceBound})
        self._data.update({"positionFill": positionFill})
        self._data.update({"clientExtensions": clientExtensions})
        self._data.update({"takeProfitOnFill": takeProfitOnFill})
        self._data.update({"stopLossOnFill": stopLossOnFill})
        self._data.update({"trailingStopLossOnFill": trailingStopLossOnFill})
        self._data.update({"tradeClientExtensions": tradeClientExtensions})

    @property
    def data(self):
        """data property.

        return the JSON body.
        """
        return dict({"order": super(StopOrderRequest, self).data})


# ============ MT4 Stop Order Executor Helper ============

class MT4StopOrderExecutor:
    """
    Helper class to execute stop orders in MT4 (replaces OANDA stop order execution)
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def execute_stop_order(self, instrument, units, price, stop_loss=None, take_profit=None):
        """
        Execute a stop order in MT4
        
        Note: MT4 stop orders are handled via market orders with price limits
        """
        try:
            # Convert units to MT4 volume (standard lots)
            volume = abs(int(units)) / 100000
            
            if units > 0:
                # BUY stop order (buy above market)
                result = self.mt4.buy(instrument, volume, stop_loss, take_profit)
            else:
                # SELL stop order (sell below market)
                result = self.mt4.sell(instrument, volume, stop_loss, take_profit)
            
            return result
        except Exception as e:
            return {'success': False, 'error': str(e)}
